from collections import namedtuple
from ute_btssm.scfc.xml.base import Xml, ScfcFixerException


class ParamDictionary(Xml):

    MANAGED_OBJECT_PATH = 'managedObject[@class="{managed_object_class}"]'
    SIMPLE_PARAM_PATH = MANAGED_OBJECT_PATH + '/p[@name="{param_name}"]'
    COMPLEX_PARAM_PATH = MANAGED_OBJECT_PATH + '/p[@name="{list_name}"]/complexType/p[@name="{param_name}"]'

    def get_simple_param(self, dist_name, param_name):
        """Returns an object representing given parameter located in a managed object (not in another param)"""
        managed_object_class = self._get_managed_object_class(dist_name)
        param_node = self._find_simple_param_node(managed_object_class, param_name)
        return Param(param_node)

    def get_complex_param(self, dist_name, list_name, param_name):
        """Returns an object representing given parameter located in a list"""
        managed_object_class = self._get_managed_object_class(dist_name)
        param_node = self._find_complex_param_node(managed_object_class, list_name, param_name)
        return Param(param_node)

    def get_managed_object(self, dist_name):
        """Returns an object representing given managed object"""
        managed_object_class = self._get_managed_object_class(dist_name)
        node = self._find_node_or_raise(self.MANAGED_OBJECT_PATH, managed_object_class=managed_object_class,
                                        exception_class=NoSuchManagedObjectInDictionary)
        return ManagedObject(node)

    def _find_simple_param_node(self, managed_object_class, param_name):
        return self._find_node_or_raise(self.SIMPLE_PARAM_PATH,
                                        managed_object_class=managed_object_class,
                                        param_name=param_name,
                                        exception_class=NoSuchParameterInDictionary)

    def _find_complex_param_node(self, managed_object_class, list_name, param_name):
        return self._find_node_or_raise(self.COMPLEX_PARAM_PATH,
                                        managed_object_class=managed_object_class,
                                        list_name=list_name,
                                        param_name=param_name,
                                        exception_class=NoSuchParameterInDictionary)


class ManagedObject(Xml):

    ALL_LIST_PARAMS_PATH = 'p[complexType]'
    ALL_SIMPLE_PARAMS_PATH = 'p[simpleType]'
    LIST_PATH = 'p[complexType][@name="{list_name}"]'

    @property
    def klass(self):
        """Returns the class of the managed object described by this dictionary entry"""
        return self.xml.get('class')

    def get_list(self, name):
        """Returns an object representing given list (a complexType parameter)"""
        node = self._find_node_or_raise(self.LIST_PATH, list_name=name, exception_class=NoSuchParameterInDictionary)
        return ListParam(node)

    def get_all_list_params(self):
        """Returns objects representing all lists (complexType parameters) that may appear in this managed object"""
        nodes = self._find_all_nodes(self.ALL_LIST_PARAMS_PATH)
        return [ListParam(node) for node in nodes]

    def get_all_simple_params(self):
        """Returns objects representing all simple params (not nested in lists) that may appear in this managed object"""
        nodes = self._find_all_nodes(self.ALL_SIMPLE_PARAMS_PATH)
        return [Param(node) for node in nodes]

    def has_id_param(self):
        """Returns true if this managed object has a parameter that represents its id, false otherwise"""
        return self.get_id_param() is not None

    def get_id_param(self):
        """Returns the parameter representing the id of this managed object, or None if no such parameter could be found"""
        for param in self.get_all_simple_params():
            if param.name.lower() == self.klass.lower() + 'id':
                return param
        return None


class ListParam(Xml):
    ALL_SIMPLE_PARAMS_PATH = 'complexType/p'

    @property
    def name(self):
        """Name of this list"""
        return self.xml.get('name')

    @property
    def mandatory(self):
        """A boolean indicating if this list is mandatory"""
        creation_node = self._find_node_or_raise('creation', exception_class=ScfcFixerException)
        return creation_node.get('priority') == 'mandatory'

    @property
    def max_occurs(self):
        """Max number of times this list may appear"""
        return int(self.xml.get('maxOccurs'))

    def get_all_params(self):
        """Returns objects representing all params that may appear in this list"""
        nodes = self._find_all_nodes(self.ALL_SIMPLE_PARAMS_PATH)
        return [Param(node) for node in nodes]


class Param(Xml):

    @property
    def name(self):
        """Name of this parameter"""
        return self.xml.get('name')

    @property
    def max_occurs(self):
        """Max number of times this parameter may appear"""
        return int(self.xml.get('maxOccurs'))

    def has_default_value(self):
        """A boolean indicating if this parameter has an explicitly defined default value"""
        return self.xml.find('simpleType//default') is not None

    @property
    def type(self):
        """Type of this parameter"""
        return self.xml.find('simpleType').attrib['base']

    @property
    def default_value(self):
        """Default value of this parameter, as stored in the XML (internal value, not UI value).
        May be none if default value is not explicitly defined for this parameter."""
        if not self.has_default_value():
            return None
        raw_default_value = self.xml.find('simpleType//default').attrib['value']
        if self.is_enum() and raw_default_value in self.enum_map:
            return self.enum_map[raw_default_value]
        elif self.is_enum() and raw_default_value not in self.enum_map:
            return self.enum_values[0]
        elif self.has_nontrivial_internal_calculation():
            return self.convert_to_internal(raw_default_value)
        else:
            return raw_default_value

    def convert_to_internal(self, value):
        """Converts the value seen in UI to the internal value stored in XML.
        Since the divisor and multiplicand parameters apply to the conversion in the opposite direction,
        we have to multiply by the divisor and divide by the multiplicand.
        The result should be an integer number (in a string)."""
        internal_value = int(float(value) * int(self.internal_divisor) / int(self.internal_multiplicand))
        return str(internal_value)

    def has_nontrivial_internal_calculation(self):
        """Returns true if this a parameter of numerical type and its internal value is different than UI value"""
        return self.internal_divisor != '1' or self.internal_multiplicand != '1'

    @property
    def internal_divisor(self):
        """Internal divisor used in conversions between the internal and UI values"""
        editing_node = self.xml.find('simpleType/editing')
        return '1' if editing_node is None else editing_node.attrib.get('divisor', '1')

    @property
    def internal_multiplicand(self):
        """Internal multiplicand used in conversions between the internal and UI values"""
        editing_node = self.xml.find('simpleType/editing')
        return '1' if editing_node is None else editing_node.attrib.get('multiplicand', '1')

    def has_value_range(self):
        """Returns true if this is parameter of numerical type and it has a defined range"""
        return self.xml.find('simpleType//range') is not None

    @property
    def value_range(self):
        """Returns the legal value range of this parameter"""
        if not self.has_value_range():
            return None
        range_node = self.xml.find('simpleType//range')
        min = range_node.attrib['minIncl']
        max = range_node.attrib['maxIncl']
        return Range(self.convert_to_internal(min), self.convert_to_internal(max))

    def has_length_range(self):
        """Returns true if this is parameter of string type and it has defined min and max length"""
        return self.xml.find('simpleType/minLength') is not None or self.xml.find('simpleType/maxLength') is not None

    @property
    def length_range(self):
        """Returns the legal length range of this parameter"""
        if not self.has_length_range():
            return None
        min_node = self.xml.find('simpleType/minLength')
        max_node = self.xml.find('simpleType/maxLength')
        min = None if min_node is None else min_node.attrib['value']
        max = None if max_node is None else max_node.attrib['value']
        return Range(min, max)

    def is_enum(self):
        """Returns true if this parameter is of enumeration type"""
        return self.xml.find('simpleType/enumeration') is not None

    @property
    def enum_map(self):
        """Returns a dictionary that maps internal ids to values for this enum parameter"""
        if not self.is_enum():
            return None
        enum_nodes = self.xml.findall('simpleType/enumeration')
        return {node.attrib['value']: node.attrib['text'] for node in enum_nodes}

    @property
    def enum_values(self):
        """Returns a list of legal values for this enum parameter"""
        if not self.is_enum():
            return None
        enum_nodes = self.xml.findall('simpleType/enumeration')
        return [node.attrib['text'] for node in enum_nodes]

    @property
    def mandatory(self):
        """Returns true if this parameter is mandatory, false if it is optional"""
        creation_node = self._find_node_or_raise('creation', exception_class=ScfcFixerException)
        return creation_node.get('priority') == 'mandatory'


class Range(namedtuple('Range', ['min', 'max'])):

    @property
    def min_as_int(self):
        """Minimum value as in int"""
        return int(self.min)

    @property
    def max_as_int(self):
        """Maximum value as in int"""
        return int(self.max)


class NoSuchParameterInDictionary(ScfcFixerException):
    """Raised when no entry for given parameter can be found in the dictionary"""


class NoSuchManagedObjectInDictionary(ScfcFixerException):
    """Raised when no entry for given managed object can be found in the dictionary"""
